func (v ConditionsValue) Equal(o attr.Value) bool {
	other, ok := o.(ConditionsValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Eq.Equal(other.Eq) {
		return false
	}

	if !v.Gt.Equal(other.Gt) {
		return false
	}

	if !v.Gte.Equal(other.Gte) {
		return false
	}

	if !v.In.Equal(other.In) {
		return false
	}

	if !v.Lt.Equal(other.Lt) {
		return false
	}

	if !v.Lte.Equal(other.Lte) {
		return false
	}

	if !v.Matches.Equal(other.Matches) {
		return false
	}

	if !v.Neq.Equal(other.Neq) {
		return false
	}

	if !v.Nin.Equal(other.Nin) {
		return false
	}

	if !v.Nnull.Equal(other.Nnull) {
		return false
	}

	if !v.Null.Equal(other.Null) {
		return false
	}

	if !v.ColumnName.Equal(other.ColumnName) {
		return false
	}

	if !v.Optional.Equal(other.Optional) {
		return false
	}

	return true
}

