func NewDataMapValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (DataMapValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing DataMapValue Attribute Value",
				"While creating a DataMapValue value, a missing attribute value was detected. "+
					"A DataMapValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("DataMapValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid DataMapValue Attribute Type",
				"While creating a DataMapValue value, an invalid attribute value was detected. "+
					"A DataMapValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("DataMapValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("DataMapValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra DataMapValue Attribute Value",
				"While creating a DataMapValue value, an extra attribute value was detected. "+
					"A DataMapValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra DataMapValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewDataMapValueUnknown(), diags
	}

	columnNameAttribute, ok := attributes["column_name"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`column_name is missing from object`)

		return NewDataMapValueUnknown(), diags
	}

	columnNameVal, ok := columnNameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`column_name expected to be basetypes.StringValue, was: %T`, columnNameAttribute))
	}

	if diags.HasError() {
		return NewDataMapValueUnknown(), diags
	}

	return DataMapValue{
		ColumnName: columnNameVal,
		state:      attr.ValueStateKnown,
	}, diags
}

