func (t UpdatesType) ValueFromObject(ctx context.Context, in basetypes.ObjectValue) (basetypes.ObjectValuable, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributes := in.Attributes()

	datetimeAttribute, ok := attributes["datetime"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`datetime is missing from object`)

		return nil, diags
	}

	datetimeVal, ok := datetimeAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`datetime expected to be basetypes.StringValue, was: %T`, datetimeAttribute))
	}

	rowsAddedAttribute, ok := attributes["rows_added"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`rows_added is missing from object`)

		return nil, diags
	}

	rowsAddedVal, ok := rowsAddedAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`rows_added expected to be basetypes.Int64Value, was: %T`, rowsAddedAttribute))
	}

	if diags.HasError() {
		return nil, diags
	}

	return UpdatesValue{
		Datetime:  datetimeVal,
		RowsAdded: rowsAddedVal,
		state:     attr.ValueStateKnown,
	}, diags
}

