func NewUpdatesValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (UpdatesValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing UpdatesValue Attribute Value",
				"While creating a UpdatesValue value, a missing attribute value was detected. "+
					"A UpdatesValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("UpdatesValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid UpdatesValue Attribute Type",
				"While creating a UpdatesValue value, an invalid attribute value was detected. "+
					"A UpdatesValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("UpdatesValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("UpdatesValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra UpdatesValue Attribute Value",
				"While creating a UpdatesValue value, an extra attribute value was detected. "+
					"A UpdatesValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra UpdatesValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewUpdatesValueUnknown(), diags
	}

	datetimeAttribute, ok := attributes["datetime"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`datetime is missing from object`)

		return NewUpdatesValueUnknown(), diags
	}

	datetimeVal, ok := datetimeAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`datetime expected to be basetypes.StringValue, was: %T`, datetimeAttribute))
	}

	rowsAddedAttribute, ok := attributes["rows_added"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`rows_added is missing from object`)

		return NewUpdatesValueUnknown(), diags
	}

	rowsAddedVal, ok := rowsAddedAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`rows_added expected to be basetypes.Int64Value, was: %T`, rowsAddedAttribute))
	}

	if diags.HasError() {
		return NewUpdatesValueUnknown(), diags
	}

	return UpdatesValue{
		Datetime:  datetimeVal,
		RowsAdded: rowsAddedVal,
		state:     attr.ValueStateKnown,
	}, diags
}

func NewUpdatesValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) UpdatesValue {
	object, diags := NewUpdatesValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewUpdatesValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t UpdatesType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewUpdatesValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewUpdatesValueUnknown(), nil
	}

	if in.IsNull() {
		return NewUpdatesValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewUpdatesValueMust(UpdatesValue{}.AttributeTypes(ctx), attributes), nil
}

func (t UpdatesType) ValueType(ctx context.Context) attr.Value {
	return UpdatesValue{}
}

